{"code":"import pandas as pd, numpy as np, statsmodels.api as sm
D=pd.read_csv('data/explore.csv'); xs=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']; S=pd.get_dummies(D.farm,drop_first=True,dtype=float)
for x in xs:
 M=sm.OLS(D['yield_kg'],sm.add_constant(pd.concat([D[[x]],S],axis=1))).fit()
 print(x, float(M.params[x]),float(M.pvalues[x]))
"}

